const INTERVALO_DIAS = 2;
const TOTAL_EMAILS = 4;
const hoje = new Date();

const templates = {
  1: {
    assunto: "Como a {{escola}} pode simplificar a gestão escolar",
    corpo: `Olá{{contatoSaudacao}},

Sou da Veloci Educacional, um sistema de gestão escolar (matrícula, financeiro, boletos, assinatura digital de documentos) pensado para o dia a dia de escolas como a {{escola}}.

Em anexo vai uma apresentação rápida do que fazemos. Queria entender como vocês lidam hoje com matrícula, cobrança e assinatura de documentos — e mostrar como podemos simplificar isso.

Topa uma conversa de 15 minutos nesta semana?

Abraço,
Equipe Veloci Educacional`
  },
  2: {
    assunto: "Re: Como a {{escola}} pode simplificar a gestão escolar",
    corpo: `Olá{{contatoSaudacao}},

Só retomando o contato anterior — sei que a rotina da escola é corrida.

Se fizer sentido, posso te mostrar em poucos minutos como escolas parceiras reduziram o trabalho manual com boletos e assinaturas de documentos.

Tem 15 minutos essa semana?

Abraço,
Equipe Veloci Educacional`
  },
  3: {
    assunto: "Um exemplo rápido para a {{escola}}",
    corpo: `Olá{{contatoSaudacao}},

Separei um exemplo rápido de como a Veloci Educacional funciona na prática para escolas do mesmo porte da {{escola}}: matrícula, emissão de boletos e assinatura digital de documentos em um só lugar.

Se quiser, te mando um vídeo curto ou agendamos uma call rápida.

Abraço,
Equipe Veloci Educacional`
  },
  4: {
    assunto: "Último contato — Veloci Educacional",
    corpo: `Olá{{contatoSaudacao}},

Esse é meu último contato por aqui — não quero ocupar sua caixa de entrada sem necessidade.

Se em algum momento a {{escola}} quiser simplificar matrícula, cobrança e assinatura de documentos, vou estar à disposição.

Abraço,
Equipe Veloci Educacional`
  }
};

const resultados = [];

for (const item of $input.all()) {
  const d = item.json;
  const status = String(d.status || "").trim().toLowerCase();

  if (status === "respondeu" || status === "parar") continue;
  if (!d.email) continue;

  const numeroEnvios = Number(d.numero_envios || 0);
  if (numeroEnvios >= TOTAL_EMAILS) continue;

  if (numeroEnvios > 0) {
    if (!d.data_ultimo_envio) continue;
    const diffDias = (hoje - new Date(d.data_ultimo_envio)) / (1000 * 60 * 60 * 24);
    if (diffDias < INTERVALO_DIAS) continue;
  }

  const proximoNumero = numeroEnvios + 1;
  const tpl = templates[proximoNumero];
  const contatoSaudacao = d.contato ? `, ${d.contato}` : "";

  resultados.push({
    json: {
      row_number: d.row_number,
      escola: d.escola,
      email: d.email,
      numero_envios_novo: proximoNumero,
      status_novo: proximoNumero >= TOTAL_EMAILS ? "finalizado" : "enviado",
      assunto: tpl.assunto.replaceAll("{{escola}}", d.escola || ""),
      corpo: tpl.corpo
        .replaceAll("{{escola}}", d.escola || "")
        .replaceAll("{{contatoSaudacao}}", contatoSaudacao),
      data_envio_hoje: hoje.toISOString().slice(0, 10)
    }
  });
}

return resultados;
